begin;
-- Extend the existing shared vault; tenant_id remains the existing property owner workspace.
alter table public.ai4cc_knowledge_entries
 add column unit_id uuid,
 add column model_section text,
 add column model_values jsonb not null default '{}'::jsonb,
 add column valid_until timestamptz,
 add constraint pm_knowledge_unit_requires_property check(unit_id is null or property_id is not null),
 add constraint pm_knowledge_unit_scope foreign key(tenant_id,property_id,unit_id) references public.pm_units(tenant_id,property_id,id),
 add constraint pm_knowledge_values_object check(jsonb_typeof(model_values)='object' and octet_length(model_values::text)<=16000),
 add constraint pm_knowledge_template_unpublished check(category not in ('pma_template','pma_agent_model_v1') or (not approved and visibility='staff')),
 add constraint pm_knowledge_internal_sections check(model_section not in ('vendors','owner_preferences') or visibility='staff');
create index pm_knowledge_scope on public.ai4cc_knowledge_entries(tenant_id,property_id,unit_id);
create unique index pm_knowledge_foundation_version on public.ai4cc_knowledge_entries(tenant_id,category) where category='pma_agent_model_v1';

create function private.pm_knowledge_guard() returns trigger language plpgsql security invoker set search_path='' as $$
declare allowed text[]; f record;
begin
 if TG_OP='UPDATE' and new.unit_id is distinct from old.unit_id then raise exception 'Immutable knowledge unit scope' using errcode='23514'; end if;
 -- Structured values are owner-supplied reference data, never authority to execute instructions.
 if new.model_section is not null and new.model_section not in ('property_profile','amenities','leasing','pet_policy','parking','move_in','move_out','property_policy','maintenance','emergency','vendors','leasing_agent','tenant_assistant','maintenance_agent','owner_preferences','intent_library','response_principles','foundation_mapping') then raise exception 'Unknown knowledge section' using errcode='23514'; end if;
 allowed=case new.model_section when 'property_profile' then array['property_id','property_name','property_type','property_status','address','city','state','zip','year_built','unit_count','office_phone','office_email','website','emergency_contact','office_hours','timezone','leasing_contact','maintenance_contact','after_hours_contact']::text[] when 'amenities' then array['amenities','pool','fitness_center','clubhouse','dog_park','playground','laundry','covered_parking','assigned_parking','storage_units','business_center','gated_access','amenity_hours.pool','amenity_hours.fitness_center','amenity_hours.clubhouse']::text[] when 'leasing' then array['accepting_applications','available_units','minimum_lease_term','application_fee','security_deposit','pet_deposit','pet_fee','income_requirement','occupancy_limits','move_in_fee','administration_fee']::text[] when 'pet_policy' then array['pets_allowed','maximum_pets','breed_restrictions','weight_limit','pet_deposit','pet_fee','monthly_pet_rent','service_animal_policy']::text[] when 'parking' then array['parking_type','visitor_parking','assigned_parking','garage','reserved_spaces','towing_policy','parking_permits','overnight_parking']::text[] when 'move_in' then array['utility_setup','required_documents','move_in_inspection','key_pickup','elevator_reservation','move_in_hours']::text[] when 'move_out' then array['required_notice','cleaning_requirements','key_return','forwarding_address','inspection_process','deposit_return']::text[] when 'property_policy' then array['quiet_hours','guest_policy','smoking_policy','grill_policy','balcony_policy','trash_policy','holiday_decorations','common_area_rules','community_access_rules']::text[] when 'maintenance' then array['categories.plumbing','categories.electrical','categories.hvac','categories.appliance','categories.pest_control','categories.structural','categories.locks','categories.internet','categories.common_area','priority.emergency','priority.high','priority.medium','priority.low']::text[] when 'emergency' then array['fire','smoke','gas_leak','flooding','electrical_hazard','security_threat','structural_threat']::text[] when 'vendors' then array['hvac.company','hvac.contact','hvac.phone','plumbing.company','plumbing.contact','plumbing.phone','electrical.company','electrical.contact','electrical.phone','locksmith.company','locksmith.contact','locksmith.phone','emergency_vendor.company','emergency_vendor.contact','emergency_vendor.phone']::text[] when 'leasing_agent' then array[]::text[] when 'tenant_assistant' then array[]::text[] when 'maintenance_agent' then array['property','unit','resident','phone','issue_type','issue_description','severity','photos','preferred_contact_method']::text[] when 'owner_preferences' then array['notification_preferences','escalation_level','vendor_preferences','after_hours_rules','emergency_vendor_rules','approval_requirements']::text[] when 'intent_library' then array[]::text[] when 'response_principles' then array[]::text[] when 'foundation_mapping' then array[]::text[] else array[]::text[] end;
 for f in select key,value from jsonb_each(new.model_values) loop
  if not f.key=any(allowed) or jsonb_typeof(f.value) not in ('string','number','boolean','null') or (jsonb_typeof(f.value)='string' and length(f.value #>> '{}')>2000) then raise exception 'Invalid structured knowledge field' using errcode='23514'; end if;
 end loop;
 if new.approved and new.content like 'UNVERIFIED TEMPLATE%' then raise exception 'Supply a reviewed answer first' using errcode='23514'; end if;
 return new;
end $$;
create trigger pm_knowledge_model_guard before insert or update on public.ai4cc_knowledge_entries for each row execute function private.pm_knowledge_guard();
revoke all on function private.pm_knowledge_guard() from public,anon;

drop policy ai4cc_knowledge_entries_select on public.ai4cc_knowledge_entries;
create policy ai4cc_knowledge_entries_select on public.ai4cc_knowledge_entries for select to authenticated using (
 (property_id is null and private.is_tenant_member(tenant_id)) or private.pm_staff(tenant_id,property_id)
 or (approved and (valid_until is null or valid_until>now()) and visibility in ('public','resident') and
 ((property_id is not null and private.pm_resident(tenant_id,property_id,null,unit_id)) or
  (property_id is null and exists(select 1 from public.pm_occupancies o where o.tenant_id=ai4cc_knowledge_entries.tenant_id and private.pm_resident(o.tenant_id,o.property_id,o.contact_id,o.unit_id))))));

-- Global foundation is materialized within each existing tenant boundary; no global tenant bypass.
insert into public.ai4cc_knowledge_entries(tenant_id,title,category,content,visibility,approved,tags)
select id,'PMA Agent Knowledge Base v1.0','pma_agent_model_v1','{"id":"ai4businesses.pma.agent-knowledge","version":"1.0","scopeHierarchy":["platform","owner","property","unit"],"missingValuePolicy":"Null, blank, expired, unapproved, ambiguous and unverified values are not facts. Ask for clarification or escalate. Never invent property policies, pricing or availability.","sections":[{"number":1,"key":"property_profile","title":"Property Profile","defaultScope":"property","fields":["property_id","property_name","property_type","property_status","address","city","state","zip","year_built","unit_count","office_phone","office_email","website","emergency_contact","office_hours","timezone","leasing_contact","maintenance_contact","after_hours_contact"]},{"number":2,"key":"amenities","title":"Property Amenities","defaultScope":"property","fields":["amenities","pool","fitness_center","clubhouse","dog_park","playground","laundry","covered_parking","assigned_parking","storage_units","business_center","gated_access","amenity_hours.pool","amenity_hours.fitness_center","amenity_hours.clubhouse"]},{"number":3,"key":"leasing","title":"Leasing Knowledge","defaultScope":"property","fields":["accepting_applications","available_units","minimum_lease_term","application_fee","security_deposit","pet_deposit","pet_fee","income_requirement","occupancy_limits","move_in_fee","administration_fee"]},{"number":4,"key":"pet_policy","title":"Pet Policy","defaultScope":"property","fields":["pets_allowed","maximum_pets","breed_restrictions","weight_limit","pet_deposit","pet_fee","monthly_pet_rent","service_animal_policy"]},{"number":5,"key":"parking","title":"Parking Policy","defaultScope":"property","fields":["parking_type","visitor_parking","assigned_parking","garage","reserved_spaces","towing_policy","parking_permits","overnight_parking"]},{"number":6,"key":"move_in","title":"Move-In Procedures","defaultScope":"property","fields":["utility_setup","required_documents","move_in_inspection","key_pickup","elevator_reservation","move_in_hours"]},{"number":7,"key":"move_out","title":"Move-Out Procedures","defaultScope":"property","fields":["required_notice","cleaning_requirements","key_return","forwarding_address","inspection_process","deposit_return"]},{"number":8,"key":"property_policy","title":"General Property Policies","defaultScope":"property","fields":["quiet_hours","guest_policy","smoking_policy","grill_policy","balcony_policy","trash_policy","holiday_decorations","common_area_rules","community_access_rules"]},{"number":9,"key":"maintenance","title":"Maintenance Knowledge","defaultScope":"property","fields":["categories.plumbing","categories.electrical","categories.hvac","categories.appliance","categories.pest_control","categories.structural","categories.locks","categories.internet","categories.common_area","priority.emergency","priority.high","priority.medium","priority.low"]},{"number":10,"key":"emergency","title":"Emergency Procedures","defaultScope":"property","fields":["fire","smoke","gas_leak","flooding","electrical_hazard","security_threat","structural_threat"]},{"number":11,"key":"vendors","title":"Vendor Knowledge","defaultScope":"owner","fields":["hvac.company","hvac.contact","hvac.phone","plumbing.company","plumbing.contact","plumbing.phone","electrical.company","electrical.contact","electrical.phone","locksmith.company","locksmith.contact","locksmith.phone","emergency_vendor.company","emergency_vendor.contact","emergency_vendor.phone"]},{"number":12,"key":"leasing_agent","title":"Leasing Agent Knowledge Model","defaultScope":"platform","fields":[]},{"number":13,"key":"tenant_assistant","title":"Tenant Assistant Knowledge Model","defaultScope":"platform","fields":[]},{"number":14,"key":"maintenance_agent","title":"Maintenance Intake Agent Knowledge Model","defaultScope":"platform","fields":["property","unit","resident","phone","issue_type","issue_description","severity","photos","preferred_contact_method"]},{"number":15,"key":"owner_preferences","title":"Property Owner Knowledge","defaultScope":"owner","fields":["notification_preferences","escalation_level","vendor_preferences","after_hours_rules","emergency_vendor_rules","approval_requirements"]},{"number":16,"key":"intent_library","title":"Property Management Intent Library","defaultScope":"platform","fields":[]},{"number":17,"key":"response_principles","title":"Response Principles","defaultScope":"platform","fields":[]},{"number":18,"key":"foundation_mapping","title":"AI4Businesses Foundation Mapping","defaultScope":"platform","fields":[]}],"intentMap":{"LEASING_INQUIRY":"leasing_inquiry","SHOWING_REQUEST":"showing_request","APPLICATION_QUESTION":"policy_question","PET_POLICY":"policy_question","PARKING_QUESTION":"policy_question","MOVE_IN":"policy_question","MOVE_OUT":"policy_question","PROPERTY_POLICY":"policy_question","MAINTENANCE_REQUEST":"maintenance_request","MAINTENANCE_STATUS":"maintenance_status","VENDOR_RESPONSE":"vendor_response","EMERGENCY":"emergency_event","OWNER_REQUEST":"unknown_question","UNKNOWN":"unknown_question"},"agents":{"leasing":{"mission":"Convert inquiries to showing requests.","allowed":["Property information","Verified availability information","Showing requests","Lead creation","Contact collection"],"prohibited":["Approve applicants","Reject applicants","Make housing decisions","Guarantee availability","Quote unverified pricing"]},"tenant":{"mission":"Resolve tenant questions.","allowed":["Approved property policies","Maintenance requests","Verified request status","Move-in support","Move-out support"],"prohibited":["Lease interpretation","Legal advice","Policy exceptions","Financial decisions"]},"maintenance":{"mission":"Create accurate maintenance requests; collect required data and identify missing information.","required":["property","unit","resident","phone","issue_type","issue_description","severity","photos","preferred_contact_method"],"optionalEvidence":["photos"],"outcome":"Complete maintenance request; mark missing details for follow-up. Never delay emergency guidance for data collection."},"emergency":{"mission":"Prioritize safety and escalate without claiming unverified action.","prohibited":["Claim emergency services contacted","Claim help is on the way","Claim issue resolved","Guarantee vendor arrival"]},"vendor":{"mission":"Coordinate authorized vendor assignments and record responses.","prohibited":["Reveal private resident data outside an authorized assignment","Close a request without property staff verification","Guarantee arrival or repairs"]},"owner":{"mission":"Assist authorized owners with scoped operations and preferences.","prohibited":["Access another owner\u2019s information","Bypass approval requirements","Make financial or housing decisions"]}},"principles":["Be accurate","Never guess","Never invent policies","Never invent availability","Never promise repairs","Never give legal advice","Never reveal private tenant data","Escalate when information is missing","Log every interaction","Prioritize safety"],"emergencyGasLeakResponse":"If you believe there is a gas leak, leave the area immediately and contact emergency services or your utility provider from a safe location. Once safe, I can record an escalation for property management. I cannot confirm that emergency services or property management have been contacted.","samples":{"availability":"I can check the latest verified property records. Availability must be confirmed by the property team. Would you like to request a showing?","application":"I can provide approved application instructions and connect you with the leasing workflow."},"foundation":["Voice Engine","SMS Engine","Web Chat Engine","Customer 360","Lead Management","Knowledge Vault","Workflow Engine","Mission Control","Analytics","Authentication","Authorization","Supabase","Netlify"],"compatibility":{"priority":{"medium":"normal"},"note":"Knowledge intents are classified separately and mapped to the existing transactional workflow enum. The medium knowledge priority maps to existing normal. Knowledge never overrides identity, permissions, safety or workflow results."},"runtimeInstructions":"Knowledge Base v1.0 \u2014 Null, blank, expired, unapproved, ambiguous and unverified values are not facts. Ask for clarification or escalate. Never invent property policies, pricing or availability.\nPrinciples: Be accurate; Never guess; Never invent policies; Never invent availability; Never promise repairs; Never give legal advice; Never reveal private tenant data; Escalate when information is missing; Log every interaction; Prioritize safety.\nLeasing agent: Convert inquiries to showing requests. Prohibited: Approve applicants; Reject applicants; Make housing decisions; Guarantee availability; Quote unverified pricing.\nTenant agent: Resolve tenant questions. Prohibited: Lease interpretation; Legal advice; Policy exceptions; Financial decisions.\nMaintenance agent: Create accurate maintenance requests; collect required data and identify missing information. Prohibited: .\nEmergency agent: Prioritize safety and escalate without claiming unverified action. Prohibited: Claim emergency services contacted; Claim help is on the way; Claim issue resolved; Guarantee vendor arrival.\nVendor agent: Coordinate authorized vendor assignments and record responses. Prohibited: Reveal private resident data outside an authorized assignment; Close a request without property staff verification; Guarantee arrival or repairs.\nOwner agent: Assist authorized owners with scoped operations and preferences. Prohibited: Access another owner\u2019s information; Bypass approval requirements; Make financial or housing decisions."}','staff',false,array['pma','canonical','v1.0'] from public.tenants
where status in ('ACTIVE','SETUP') on conflict do nothing;

-- The definer channel path must authorize the *contact audience*, not just its staff actor.
create function private.pm_knowledge_answer(t uuid,p uuid,c uuid,u uuid,msg text) returns jsonb language plpgsql stable security invoker set search_path='' as $$
declare answers jsonb;
begin
 if not private.pm_staff(t,p,true) then raise exception 'Forbidden' using errcode='42501'; end if;
 with candidates as (
  select k.*,case when k.unit_id is not null then 3 when k.property_id is not null then 2 else 1 end as rank
  from public.ai4cc_knowledge_entries k where k.tenant_id=t and (k.property_id=p or k.property_id is null)
   and (k.unit_id is null or (u=k.unit_id and exists(select 1 from public.pm_occupancies o where o.tenant_id=t and o.property_id=p and o.unit_id=u and o.contact_id=c and o.status='active' and o.starts_on<=current_date and (o.ends_on is null or o.ends_on>=current_date))))
   and k.approved and k.visibility in ('public','resident') and (k.valid_until is null or k.valid_until>now())
   and (k.visibility='public' or exists(select 1 from public.pm_occupancies o where o.tenant_id=t and o.property_id=p and o.contact_id=c and o.status='active' and o.starts_on<=current_date and (o.ends_on is null or o.ends_on>=current_date) and (u is null or o.unit_id=u)))
   and to_tsvector('english',k.title||' '||k.content)@@plainto_tsquery('english',msg)
 ) select jsonb_agg(to_jsonb(x) order by x.updated_at desc,x.id) into answers from candidates x where rank=(select max(rank) from candidates);
 if answers is null then return jsonb_build_object('reply','I do not have an approved current answer for this property and contact. The property team needs to review your question.','requiresHumanReview',true); end if;
 if jsonb_array_length(answers)>1 then return jsonb_build_object('reply','I found multiple approved answers and need the property team to confirm which applies.','requiresHumanReview',true,'knowledgeConflict',true); end if;
 return jsonb_build_object('reply',answers->0->>'content','knowledgeId',answers->0->>'id','knowledgeScope',case (answers->0->>'rank')::integer when 3 then 'unit' when 2 then 'property' else 'owner' end,'requiresHumanReview',false);
end $$;
revoke all on function private.pm_knowledge_answer(uuid,uuid,uuid,uuid,text) from public,anon;
grant execute on function private.pm_knowledge_answer(uuid,uuid,uuid,uuid,text) to authenticated,service_role;
create or replace function private.pm_record_channel_turn(t uuid,p uuid,c uuid,u uuid,k text,ch text,msg text,intent text,category text,priority text,show_at timestamptz default null,request_id uuid default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare i public.ai4cc_interactions; req public.pm_maintenance_requests; showing public.pm_showings; lead uuid; answer text; kb public.ai4cc_knowledge_entries; outcome jsonb; q text;
begin
 if not private.pm_staff(t,p,true) then raise exception 'Forbidden' using errcode='42501'; end if;
 if ch not in ('voice','sms','chat') or length(k) not between 8 and 160 or length(msg) not between 1 and 4000 then raise exception 'Invalid channel input' using errcode='23514'; end if;
 if intent not in ('leasing_inquiry','showing_request','maintenance_request','maintenance_status','policy_question','tenant_question','vendor_response','emergency_event','unknown_question') then raise exception 'Invalid intent' using errcode='23514'; end if;
 if not exists(select 1 from public.ai4cc_contacts where tenant_id=t and id=c) then raise exception 'Contact not found' using errcode='23503'; end if;
 if not exists(select 1 from public.pm_properties where tenant_id=t and id=p and status='active') then raise exception 'Property unavailable' using errcode='23514'; end if;
 if u is not null and not exists(select 1 from public.pm_units where tenant_id=t and property_id=p and id=u) then raise exception 'Invalid property unit' using errcode='23503'; end if;
 perform pg_advisory_xact_lock(hashtextextended(t::text||':pma-channel:'||k,0));
 select * into i from public.ai4cc_interactions where tenant_id=t and external_id='pma:'||ch||':'||k;
 if found then
   if i.metadata->>'property_id'<>p::text or i.metadata->>'contact_id'<>c::text or i.metadata->>'message_hash'<>md5(jsonb_build_object('msg',msg,'unit',u,'intent',intent,'category',category,'priority',priority,'show_at',show_at,'request_id',request_id)::text) then raise exception 'Channel operation key conflict' using errcode='23514'; end if;
   return (i.metadata->'outcome')||jsonb_build_object('replayed',true);
 end if;
 insert into public.ai4cc_interactions(tenant_id,channel,direction,external_id,customer_identifier,status,ended_at,metadata)
 values(t,ch,'inbound','pma:'||ch||':'||k,c::text,'completed',now(),jsonb_build_object('source','pma','property_id',p,'contact_id',c,'intent',intent,'sandbox',true,'message_hash',md5(jsonb_build_object('msg',msg,'unit',u,'intent',intent,'category',category,'priority',priority,'show_at',show_at,'request_id',request_id)::text))) returning * into i;
 answer='Please clarify your question so the property team can assist.';
 outcome=jsonb_build_object('intent',intent,'interactionId',i.id,'persisted',true,'notificationSent',false,'emergencyServicesContacted',false,'vendorArrivalConfirmed',false,'issueResolved',false,'requiresHumanReview',false);
 if intent in ('maintenance_request','emergency_event') then
   insert into public.pm_maintenance_requests(tenant_id,property_id,unit_id,contact_id,interaction_id,summary,description,category,priority,source_channel,idempotency_key)
   values(t,p,u,c,i.id,left(msg,500),msg,category,case when intent='emergency_event' then 'emergency' else priority end,ch,'channel:'||ch||':'||k) returning * into req;
   answer='Your request has been recorded. Reference: '||req.id::text||'. Status: New. The property team will review it.';
   if intent='emergency_event' then answer='If you are in immediate danger, move to a safe location and contact local emergency services. I cannot confirm emergency dispatch. '||answer; end if;
   outcome=outcome||jsonb_build_object('requestId',req.id,'status',req.status,'requiresHumanReview',intent='emergency_event');
 elsif intent in ('leasing_inquiry','showing_request') then
   if intent='showing_request' and show_at is not null then
     showing=public.pm_request_showing(t,p,u,c,show_at,msg,'channel:'||ch||':'||k);
     lead=showing.lead_id;
     outcome=outcome||jsonb_build_object('showingId',showing.id,'showingStatus','requested');
   else
     insert into public.ai4cc_leads(tenant_id,contact_id,originating_interaction_id,originating_channel,title,service_interest,description,metadata)
     values(t,c,i.id,ch,'Property leasing inquiry','Property leasing',msg,jsonb_build_object('source','pma','property_id',p)) returning id into lead;
   end if;
   update public.ai4cc_leads set originating_interaction_id=i.id,originating_channel=ch where tenant_id=t and id=lead;
   answer='Your leasing inquiry has been recorded. The property team must confirm current availability and any showing time. No application or housing decision has been made.';
   outcome=outcome||jsonb_build_object('leadId',lead,'availabilityGuaranteed',false,'requiresClarification',intent='showing_request' and show_at is null);
 elsif intent='maintenance_status' then
   if request_id is not null then
     select * into req from public.pm_maintenance_requests where tenant_id=t and property_id=p and id=request_id and contact_id=c;
     if found then answer='Request '||req.id::text||' has status '||req.status||'.'; outcome=outcome||jsonb_build_object('requestId',req.id,'status',req.status);
     else answer='I could not verify that request for this contact and property.'; end if;
   else answer='Please provide your request reference so its status can be verified.'; end if;
 elsif intent in ('policy_question','tenant_question') then
   outcome=outcome||private.pm_knowledge_answer(t,p,c,u,msg);
   answer=outcome->>'reply';
 elsif intent='vendor_response' then
   answer='Please use your authenticated vendor assignment to accept, decline or report completed work.';
 else outcome=outcome||jsonb_build_object('requiresHumanReview',true);
 end if;
 outcome=outcome||jsonb_build_object('reply',answer);
 insert into public.ai4cc_transcripts(tenant_id,interaction_id,speaker,sequence_no,content,metadata) values
 (t,i.id,'customer',1,msg,jsonb_build_object('source','pma','sandbox',true)),
 (t,i.id,'agent',2,answer,jsonb_build_object('source','pma','sandbox',true));
 update public.ai4cc_interactions set metadata=i.metadata||jsonb_build_object('outcome',outcome) where tenant_id=t and id=i.id;
 return outcome;
end;
$$;
create or replace function private.pm_available_properties() returns jsonb language sql stable security definer set search_path='' as $$
 select case when auth.uid() is null then '[]'::jsonb else coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'amenities',p.amenities,
 'availabilityRequiresConfirmation',true,'knowledge',(select coalesce(jsonb_agg(jsonb_build_object('title',k.title,'content',k.content)),'[]'::jsonb) from public.ai4cc_knowledge_entries k where k.tenant_id=p.tenant_id and k.property_id=p.id and k.approved and k.visibility='public' and k.unit_id is null and (k.valid_until is null or k.valid_until>now())))),'[]'::jsonb) end
 from public.pm_properties p join public.tenants w on w.id=p.tenant_id where p.accepts_inquiries and p.status='active' and w.status='ACTIVE';
$$;
alter table public.pm_maintenance_requests drop constraint pm_maintenance_requests_category_check;
alter table public.pm_maintenance_requests add constraint pm_maintenance_requests_category_check check(category in ('plumbing','electrical','hvac','structural','appliance','pest_control','locks','internet','common_area','other'));
commit;
